from pathlib import Path
import gzip,base64
root=Path(__file__).resolve().parents[1]
payloads={
'data/capacity/normalized/1401/capacities-food-science-vet-associate-meat-inspection.csv': '',
'data/capacity/normalized/1402/capacities-food-science-vet-associate-meat-inspection.csv': '',
'data/capacity/normalized/1403/capacities-food-science-vet-associate-meat-inspection.csv': '',
'data/capacity/normalized/1404/capacities-food-science-vet-associate-meat-inspection.csv': '',
'data/capacity/FOOD_SCIENCE_VET_ASSOCIATE_MEAT_REPORT.md': '',
'data/capacity/FOOD_SCIENCE_VET_ASSOCIATE_MEAT_SUMMARY.json': '',
}
for rel,data in payloads.items():
    p=root/rel
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_bytes(gzip.decompress(base64.b64decode(data)))
    print('wrote',rel)
